private static boolean sourceTemplateFlag(FieldDescriptor field, String attribute) {
  String value = field.getAttributeValue(attribute);
  if (value == null || value.isEmpty()) { return false; }
  return !Set.of("false", "off", "no").contains(value.toLowerCase(Locale.ROOT));
}

// The source adaptor resolves nonempty attributes before JavaBean methods.
// In particular float inherits isNumber=true despite FieldDescriptor.isNumber().

private static boolean sourceNumericField(FieldDescriptor field) {
  String value = field.getAttributeValue("isNumber");
  return value == null || value.isEmpty() ? field.isNumber() : sourceTemplateFlag(field, "isNumber");
}

private void queryFieldCriteria(StringBuilder out, String request, FieldDescriptor fd) {
  if (fd.isVersion() || fd.isBoolean() || fd.isObjectProperty() || CppBusinessIdMetadata.isBusinessId(fd)) {
    return;
  }
  String prefix = camel(identifier(FieldDescriptorNaming.attributePredicatePrefixExpr(fd)));
  String field = quote(canonical(fd));
  String rangeTemplate = "template <std::ranges::input_range Inputs> requires std::constructible_from<Value, Memory, std::ranges::range_reference_t<Inputs>> ";
  String scalarTemplate = "template <class Input> requires std::constructible_from<Value, Memory, const Input&> ";
  if (baseType(fd).equals("String") && !fd.getBooleanAttribute("isText") && !fd.getBooleanAttribute("isPassword")) {
    String soundName = camel(identifier(FieldDescriptorNaming.attributePredicatePrefixExpr(fd)
        + "Sound" + FieldDescriptorNaming.attributePredicateSuffixExpr(fd) + "Like"));
    fluent(out, request, scalarTemplate, soundName, "const Input& value", "value",
        "query_.andFilter(Expr::sound_like(memory_resource(), " + field + ", value));");
  }
  for (String[] comparison : List.of(new String[]{"Is", "eq"}, new String[]{"IsNot", "ne"},
      new String[]{"GreaterThan", "gt"}, new String[]{"GreaterThanOrEqualTo", "gte"},
      new String[]{"LessThan", "lt"}, new String[]{"LessThanOrEqualTo", "lte"})) {
    if (fd.isId() && !comparison[0].equals("Is") && !comparison[0].equals("IsNot")) { continue; }
    fluent(out, request, scalarTemplate, prefix + comparison[0], "const Input& value", "value",
        "query_.andFilter(Expr::" + comparison[1] + "(memory_resource(), " + field + ", value));");
  }
  if (!fd.isId()) {
    String betweenTemplate = "template <class Lower, class Upper> requires std::constructible_from<Value, Memory, const Lower&> && std::constructible_from<Value, Memory, const Upper&> ";
    fluent(out, request, betweenTemplate, prefix + "Between", "const Lower& lower, const Upper& upper", "lower, upper",
        "query_.andFilter(Expr::between(memory_resource(), " + field + ", lower, upper));");
  }
  for (String suffix : List.of("In", "NotIn")) {
    fluent(out, request, rangeTemplate, prefix + suffix,
        "Inputs&& inputs", "std::forward<Inputs>(inputs)",
        "query_.filterField(" + field + ", request::FieldOperator::" + suffix
            + ", std::forward<Inputs>(inputs));");
  }
  fluent(out, request, rangeTemplate, prefix,
      "request::FieldOperator op, Inputs&& inputs", "op, std::forward<Inputs>(inputs)",
      "query_.filterField(" + field + ", op, std::forward<Inputs>(inputs));");
  line(out, rangeTemplate + "Ref<Expr> " + camel("create_" + fieldName(fd) + "_criteria")
      + "(request::FieldOperator op, Inputs&& inputs) const { return query_.createFieldCriteria("
      + field + ", op, std::forward<Inputs>(inputs)); }");
  if (!fd.isId()) {
    String valueTemplate = "template <class T> requires std::constructible_from<Value, Memory, const T&> ";
    fluent(out, request, valueTemplate, prefix + "BetweenRange",
        "const request::DateRange<T>& range", "range",
        "query_.andFilter(Expr::between(memory_resource(), " + field + ", range.start, range.end));");
    for (String suffix : List.of("Before", "After")) {
      fluent(out, request, valueTemplate, prefix + suffix, "const T& value", "value",
          "query_.andFilter(Expr::" + (suffix.equals("Before") ? "lt" : "gt")
          + "(memory_resource(), " + field + ", value));");
    }
  }
}

private void queryField(StringBuilder out, String request, FieldDescriptor fd) {
  String member = fieldName(fd), canonical = quote(canonical(fd));
  String sourceMember = RustFieldDescriptorNaming.rustStorageMemberName(fd);
  String prefix = identifier(FieldDescriptorNaming.attributePredicatePrefixExpr(fd));
  for (Candidate candidate : candidates(fd)) {
    for (boolean negative : List.of(false, true)) {
      String method = prefix + (negative ? "_is_not_" : "_is_")
          + candidate.getRustCandidateMethodValue();
      line(out, request + "& " + method
          + "() { selection.and_filter(Expr::" + (negative ? "ne" : "eq")
          + "(memory_resource(), " + canonical + ", "
          + candidateLiteral(fd, candidate) + ")); return *this; }");
    }
  }
  line(
      out,
      request
          + "& select_"
          + member
          + "() { selection.project("
          + canonical
          + "); return *this; }");
  if (!fd.isId() && !fd.isVersion()) {
    fieldAdapter(out, request, camel("project_" + member), "", "", "query_.select(" + canonical + ");");
    fieldAdapter(out, request, camel("select_" + member + "_raw"), "std::string_view sql", "sql", "query_.selectRaw(" + canonical + ", sql);");
    fieldAdapter(out, request, camel("select_" + member + "_unsafe_raw"), "request::UnsafeRawSqlSegment sql", "std::move(sql)", "query_.selectUnsafeRaw(" + canonical + ", std::move(sql));");
    if (!fd.isObjectProperty()) {
      fieldAdapter(out, request, camel("unselect_" + member), "", "", "query_.unselect(" + canonical + ");");
    }
    if (fd.isObjectProperty()) {
      fieldAdapter(out, request, camel("unselect_" + relationName(fd)), "", "", "query_.unselectRelation(" + canonical + ", " + quote(relationIdentity(fd)) + ");");
    }
    if (sourceNumericField(fd)) {
      fieldAdapter(out, request, camel("select_" + member + "_with_function"), "AggregateFunction function", "function", "query_.selectWithFunction(" + canonical + ", " + canonical + ", function);");
      fieldAdapter(out, request, camel("select_" + member + "_as_with_function"), "std::string_view alias, AggregateFunction function", "alias, function", "query_.selectWithFunction(" + canonical + ", alias, function);");
    }
  }
  for (String direction : List.of("asc", "desc")) {
    line(
        out,
        request
            + "& order_by_"
            + member
            + "_"
            + direction
            + "() { selection.order_"
            + direction
            + "("
            + canonical
            + "); return *this; }");
  }
  for (String direction : List.of("asc", "desc")) {
    line(out, request + "& order_by_" + member + "_" + direction + "_using_gbk() { selection.order_gbk_" + direction + "(" + canonical + "); return *this; }");
  }
  if (fd.isBoolean()) {
    line(
        out,
        request
            + "& "
            + identifier(FieldDescriptorNaming.snakeBooleanPredicateExpr(fd))
            + "() { selection.and_filter(Expr::eq(memory_resource(), "
            + canonical
            + ", true)); return *this; }");
    line(
        out,
        request
            + "& "
            + identifier(FieldDescriptorNaming.snakeBooleanNegativePredicateExpr(fd))
            + "() { selection.and_filter(Expr::eq(memory_resource(), "
            + canonical
            + ", false)); return *this; }");
  }
  for (String[] pair :
      List.of(
          new String[] {"is", "eq"},
          new String[] {"is_not", "ne"},
          new String[] {"greater_than", "gt"},
          new String[] {"greater_than_or_equal_to", "gte"},
          new String[] {"less_than", "lt"},
          new String[] {"less_than_or_equal_to", "lte"})) {
    line(
        out,
        request
            + "& "
            + prefix
            + "_"
            + pair[0]
            + "("
            + predicateType(fd)
            + " value) { selection.and_filter(Expr::"
            + pair[1]
            + "(memory_resource(), "
            + canonical
            + ", generated_detail::encode(memory_resource(), value))); return *this; }");
  }
  line(
      out,
      request
          + "& "
          + prefix
          + "_between("
          + predicateType(fd)
          + " lower, "
          + predicateType(fd)
          + " upper) { selection.and_filter(Expr::between(memory_resource(), "
          + canonical
          + ", generated_detail::encode(memory_resource(), lower),"
          + " generated_detail::encode(memory_resource(), upper))); return *this; }");
  for (String suffix : List.of("in", "not_in")) {
    line(
        out,
        request
            + "& "
            + prefix
            + "_"
            + suffix
            + "(std::span<const "
            + (CppBusinessIdMetadata.isBusinessId(fd) ? applicationType(fd) : baseType(fd))
            + "> inputs) { auto r = memory_resource(); Vector<Value> values(r); for (const auto&"
            + " value : inputs) { values.emplace_back(generated_detail::encode(r, value)); }"
            + " selection.and_filter(Expr::in_list(r, "
            + canonical
            + ", values, "
            + suffix.equals("not_in")
            + ")); return *this; }");
  }
  String aggregateMember = fd.isObjectProperty() ? relationName(fd) : member;
  String sourceCountMember = fd.isObjectProperty()
      ? RustFieldDescriptorNaming.rustMemberName(fd) : sourceMember;
  fieldAdapter(out, request, camel("group_by_" + aggregateMember), "", "",
      "query_.groupBy(" + canonical + ");");
  fieldAdapter(out, request, camel("group_by_" + aggregateMember + "_as"), "std::string_view alias", "alias",
      "query_.groupBy(" + canonical + "); query_.selectAs(" + canonical + ", alias);");
  fieldAdapter(out, request, camel("group_by_" + aggregateMember + "_with_function"),
      "std::string_view alias, AggregateFunction function", "alias, function",
      "query_.groupBy(" + canonical + "); query_.aggregateWithFunction(" + canonical + ", alias, function);");
  fieldAdapter(out, request, camel("count_" + aggregateMember), "", "",
      "query_.aggregateCountField(" + canonical + ", " + quote(sourceCountMember + "_count") + ");");
  fieldAdapter(out, request, camel("count_" + aggregateMember + "_as"), "std::string_view alias", "alias",
      "query_.aggregateCountField(" + canonical + ", alias);");
  if (!fd.isObjectProperty()) {
    for (String method : List.of("sum", "avg", "min", "max")) {
      fieldAdapter(out, request, camel(method + "_" + member), "", "",
          "query_." + camel("aggregate_" + method) + "(" + canonical + ", " + quote(method + "_" + sourceMember) + ");");
      fieldAdapter(out, request, camel(method + "_" + member + "_as"), "std::string_view alias", "alias",
          "query_." + camel("aggregate_" + method) + "(" + canonical + ", alias);");
    }
    if (sourceNumericField(fd)) {
      for (String[] method : List.of(
          new String[]{"standard_deviation", "aggregateStddev", "stdDev"},
          new String[]{"square_root_of_population_standard_deviation", "aggregateStddevPop", "stdDevPop"},
          new String[]{"sample_variance", "aggregateVarSamp", "varSamp"},
          new String[]{"sample_population_variance", "aggregateVarPop", "varPop"})) {
        fieldAdapter(out, request, camel(method[0] + "_" + member), "", "",
            "query_." + method[1] + "(" + canonical + ", " + quote(method[2] + "_" + sourceMember) + ");");
        fieldAdapter(out, request, camel(method[0] + "_" + member + "_as"), "std::string_view alias", "alias",
            "query_." + method[1] + "(" + canonical + ", alias);");
      }
    }
  }
  if (baseType(fd).equals("String")) {
    line(
        out,
        request
            + "& "
            + identifier(FieldDescriptorNaming.stringContainsPredicateExpr(fd))
            + "(std::string_view value) { selection.and_filter(Expr::contain(memory_resource(), "
            + canonical
            + ", value)); return *this; }");
    line(
        out,
        request
            + "& "
            + identifier(FieldDescriptorNaming.StringStartsWithPredicateExpr(fd))
            + "(std::string_view value) {"
            + " selection.and_filter(Expr::begin_with(memory_resource(), "
            + canonical
            + ", value)); return *this; }");
    line(
        out,
        request
            + "& "
            + identifier(FieldDescriptorNaming.StringEndsWithPredicateExpr(fd))
            + "(std::string_view value) { selection.and_filter(Expr::end_with(memory_resource(), "
            + canonical
            + ", value)); return *this; }");
  }
  if (baseType(fd).equals("String") && !CppBusinessIdMetadata.isBusinessId(fd)
      && !fd.getBooleanAttribute("isText") && !fd.getBooleanAttribute("isPassword")) {
    for (String[] method : List.of(
        new String[]{"NotContain", "not_contain", ""},
        new String[]{"NotStart", "not_begin_with", "With"},
        new String[]{"NotEnd", "not_end_with", "With"},
        new String[]{"Sound", "sound_like", "Like"})) {
      String methodName = identifier(FieldDescriptorNaming.attributePredicatePrefixExpr(fd)
          + method[0] + FieldDescriptorNaming.attributePredicateSuffixExpr(fd) + method[2]);
      line(out, request + "& " + methodName + "(std::string_view value) { selection.and_filter(Expr::"
          + method[1] + "(memory_resource(), " + canonical + ", value)); return *this; }");
    }
  }
  Set<String> candidateNames = new HashSet<>();
  for (Candidate candidate : candidates(fd)) {
    candidateNames.add(camel(prefix + "_is_" + candidate.getRustCandidateMethodValue()));
    candidateNames.add(camel(prefix + "_is_not_" + candidate.getRustCandidateMethodValue()));
  }
  // Source Unknown/Known denote SQL NULL availability. Keep established C++
  // Null/NotNull aliases only when a real candidate does not occupy that name.
  for (String[] method : List.of(new String[]{"is_unknown", "is_null"},
      new String[]{"is_known", "is_not_null"}, new String[]{"is_null", "is_null"},
      new String[]{"is_not_null", "is_not_null"})) {
    if (!candidateNames.contains(camel(prefix + "_" + method[0]))) {
      line(out, request + "& " + prefix + "_" + method[0]
          + "() { selection.and_filter(Expr::" + method[1] + "(memory_resource(), "
          + canonical + ")); return *this; }");
    }
  }
}

private static List<FieldDescriptor> descriptorFields(ObjectDescriptor od) {
  return java.util.stream.Stream.concat(
      fields(od).stream().filter(field -> !field.isObjectProperty()),
      fields(od).stream().filter(FieldDescriptor::isObjectProperty)).toList();
}

private String models(String ns, List<ObjectDescriptor> entities) {
  StringBuilder out = new StringBuilder(header(ns, "support.hpp"));
  if (hasGeneratedBootstrap(entities)) {
    line(out, "namespace generated_detail {");
    for (ObjectDescriptor entity : entities) {
      line(out, "struct " + typeName(entity) + "BootstrapRecipe;");
    }
    line(out, "}");
  }
  line(out, "namespace generated_detail {");
  for (ObjectDescriptor entity : entities) { line(out, "struct " + typeName(entity) + "SampleRecipe;"); }
  line(out, "}");
  Set<FieldDescriptor> businessFields = java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>());
  for (ObjectDescriptor od : entities) {
    line(out, "struct " + typeName(od) + "; class " + typeName(od) + "Checker;");
  }
  for (ObjectDescriptor od : entities) {
    for (FieldDescriptor field : fields(od)) {
      if (CppBusinessIdMetadata.isBusinessId(field) && businessFields.add(field)) {
        businessIdType(out, field);
      }
    }
  }
  for (ObjectDescriptor od : entities) {
    String name = typeName(od);
    line(out, "struct " + name + " : generated_detail::Model<" + name + "> {");
    line(
        out,
        "using Base = generated_detail::Model<" + name + ">; friend class " + name + "Checker;");
    line(out, "static constexpr std::string_view ENTITY_NAME = " + quote(name) + ";");
    line(out, "friend struct generated_detail::" + name + "SampleRecipe;");
    if (hasGeneratedBootstrap(entities)) {
      line(out, "friend struct generated_detail::" + name + "BootstrapRecipe;");
    }
    List<FieldDescriptor> identityFields = od.getFields().stream()
        .filter(field -> field.isId() || field.isVersion()).toList();
    line(out, "static constexpr std::array<std::string_view, " + identityFields.size()
        + "> QUERY_IDENTITY_FIELDS{" + identityFields.stream().map(field -> quote(canonical(field)))
            .collect(java.util.stream.Collectors.joining(", ")) + "};");
    List<FieldDescriptor> projectionFields = descriptorFields(od);
    if (projectionFields.stream().anyMatch(field -> !canonical(field).equals(
        RustFieldDescriptorNaming.rustStorageMemberName(field)))) {
      line(out, "static constexpr std::array<std::string_view, " + projectionFields.size()
          + "> QUERY_PROJECTION_FIELDS{" + projectionFields.stream().map(field -> quote(canonical(field)))
              .collect(java.util.stream.Collectors.joining(", ")) + "};");
    }
    line(out, "private:");
    for (FieldDescriptor fd : fields(od)) {
      line(out, storageType(fd) + " " + fieldName(fd) + "_;");
    }
    for (FieldDescriptor fd :
        fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
      line(
          out,
          "detail::ScopedBox<"
              + typeName(((ObjectType) fd.getFieldType()).getRefer())
              + "> "
              + relationName(fd)
              + "_;");
    }
    for (ReverseRelation rel : od.getReverseRelations()) {
      line(
          out,
          (ReverseRelationNaming.oneToOne(rel) ? "detail::ScopedBox<" : "SmartList<")
              + typeName(rel.getChild())
              + "> "
              + relationName(rel)
              + "_;");
    }
    line(out, "public:");
    line(out, name + "(std::allocator_arg_t, Allocator);");
    line(out, name + "(std::allocator_arg_t, Allocator, const " + name + "&);");
    line(
        out,
        name
            + "(std::allocator_arg_t, Allocator a, "
            + name
            + "&& other) : "
            + name
            + "(std::allocator_arg, a, std::as_const(other)) {} ");
    // The allocator-aware move delegates to copy into the destination below.
    line(out, name + "(const " + name + "&) = delete;");
    line(out, name + "(" + name + "&&) noexcept;");
    line(out, "~" + name + "();");
    line(out, "static EntityDescriptor entity_descriptor(Memory);");
    emitFieldLayout(out, od);

    line(out, "static Result<" + name + ", EntityError> from_compact_row(Memory, CompactRow);");
    line(out, "std::optional<Json> borrowed_json(Memory, EntityJsonTraversal&) const;");
    line(out, "MutationValues into_values() &&;");
    line(out, "void attachRuntimeStateRecursive(const EntityRuntimeState&);");
    for (FieldDescriptor fd : fields(od)) {
      String field = fieldName(fd);
      boolean storedOnly = fd.getBooleanAttribute("optional") || baseType(fd).equals("Json");
      line(
          out,
          (storedOnly ? "const " + storageType(fd) + "&" : applicationType(fd))
              + " "
              + field
              + "() const { return "
              + (storedOnly
                  ? field + "_"
                  : (CppBusinessIdMetadata.isBusinessId(fd)
                          ? "GeneratedBusinessIdAccess::from_canonical<"
                              + applicationType(fd)
                              + ">("
                              + "memory_resource(), "
                          : "")
                      + "detail::EntityRuntimeAccess::current_field(root, entity_key(), "
                      + quote(canonical(fd))
                      + ", "
                      + field
                      + "_)"
                      + (CppBusinessIdMetadata.isBusinessId(fd) ? ")" : ""))
              + "; }");
      if (fd.isId()) {
        line(out, storageType(fd) + " id_for_runtime() const { return " + field + "_; }");
      }
      line(
          out,
          "std::optional<Value> "
              + camel("changed_" + field)
              + "() const { return root.get(entity_key(), "
              + quote(canonical(fd))
              + "); }");
      line(
          out,
          "eval::EvalResult<"
              + applicationType(fd)
              + "> "
              + camel("eval_" + field)
              + "() const { return detail::EntityRuntimeAccess::eval_field<"
              + applicationType(fd)
              + ">(memory_resource(), load_state, "
              + quote(canonical(fd))
              + ", [this] { return detail::clone_in(memory_resource(), "
              + field
              + "()); }); }");
      if (fd.isContextRoot() || fd.isConstantObjectField()) {
        line(out, "private: // Scoped and constant assignments belong to generated runtime code.");
      }
      line(out, name + "& update_" + field + "(" + argumentType(fd) + " value) {");
      boolean textField = !CppBusinessIdMetadata.isBusinessId(fd) && baseType(fd).equals("String");
      if (textField) {
        line(out, "detail::EntityRuntimeAccess::update_text(root, entity_key(), "
            + quote(canonical(fd)) + ", " + field + "_, value);");
      } else {
        if (CppBusinessIdMetadata.isBusinessId(fd)) {
          line(out, field + "_.assign(value.asStr());");
        } else {
          line(out, field + "_ = detail::clone_in(memory_resource(), value);");
        }
        line(out, "root.set(entity_key(), " + quote(canonical(fd))
            + ", generated_detail::encode(memory_resource(), " + field + "_));");
      }
      line(out, "load_state.mark_loaded(" + quote(canonical(fd))
          + ", &detail::ContextArena::from_memory(memory_resource()).loaded_snapshots()).value();"
          + " return *this; }");
      if (fd.isContextRoot() || fd.isConstantObjectField()) {
        line(out, "public:");
      }
      if (fd.isVersion()) {
        line(out, "std::int64_t version_value() const { return " + field + "_; }");
      }
    }
    for (FieldDescriptor field : fields(od)) {
      if (!field.isConstantObjectField()) { continue; }
      for (Candidate candidate : candidates(field)) {
        String suffix = candidate.getRustCandidateMethodValue();
        line(out, name + "& " + camel("update_" + relationName(field) + "_to_" + suffix)
            + "() { return " + camel("update_" + fieldName(field)) + "("
            + candidateLiteral(field, candidate) + "); }");
        line(out, "bool " + camel(relationName(field) + "_is_" + suffix)
            + "() const { return " + camel(fieldName(field)) + "() == "
            + candidateLiteral(field, candidate) + "; }");
      }
    }
    for (FieldDescriptor fd :
        fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
      String target = typeName(((ObjectType) fd.getFieldType()).getRefer());
      line(out, "const " + target + "* " + relationName(fd) + "() const;");
      if (fd.isContextRoot() || fd.isConstantObjectField()) {
        line(out, "private:");
      }
      line(out, name + "& update_" + relationName(fd) + "(const " + target + "& value);");
      if (fd.isContextRoot() || fd.isConstantObjectField()) {
        line(out, "public:");
      }
      relationEvalDeclaration(out, relationName(fd), target, false);
    }
    for (ReverseRelation rel : od.getReverseRelations()) {
      String target = typeName(rel.getChild()), member = relationName(rel);
      if (ReverseRelationNaming.oneToOne(rel)) {
        line(out, "const " + target + "* " + member + "() const;");
      } else {
        line(out, "const SmartList<" + target + ">& " + member + "() const;");
        line(out, "SmartList<" + target + ">& " + member + "();");
      }
      boolean many = !ReverseRelationNaming.oneToOne(rel);
      relationEvalDeclaration(out, member, target, many);
      line(
          out,
          "RelationHandle<"
              + (many ? "SmartList<" + target + ">" : target)
              + "> "
              + camel(member + "_handle")
              + "() const;");
    }
    line(out, "};");
  }
  for (ObjectDescriptor od : entities) {
    modelDefinitions(out, od);
  }
  line(out, "}");
  return camelModelMethods(out.toString(), entities);
}

private void modelDefinitions(StringBuilder out, ObjectDescriptor od) {
  relationAccessors(out, od);
  relationEvaluations(out, od);
  jsonProjection(out, od);
  String name = typeName(od);
  line(out, "inline void " + name
      + "::attachRuntimeStateRecursive(const EntityRuntimeState& target) {");
  line(out, "root.attach_runtime_state(target);");
  for (FieldDescriptor field : fields(od)) {
    if (field.isObjectProperty()) {
      String member = relationName(field) + "_";
      line(out, "if (" + member + ") { " + member
          + "->attachRuntimeStateRecursive(target); }");
    }
  }
  line(out, "}");
  StringBuilder init = new StringBuilder(": Base(std::allocator_arg, a)");
  StringBuilder copy = new StringBuilder(": Base(std::allocator_arg, a, other)");
  for (FieldDescriptor fd : fields(od)) {
    String member = fieldName(fd) + "_";
    boolean clockDefault = "Timestamp".equals(baseType(fd))
        && "teaql_core::time::Timestamp::now()".equals(RustFieldDescriptorNaming.rustDefaultValue(fd));
    init.append(", ")
        .append(member)
        .append(clockDefault ? "(Timestamp::now())" : "(generated_detail::default_value<"
            + storageType(fd) + ">(a.resource()))");
    copy.append(", ")
        .append(member)
        .append("(detail::clone_in(a.resource(), other.")
        .append(member)
        .append("))");
  }
  for (FieldDescriptor fd :
      fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
    String member = relationName(fd) + "_";
    init.append(", ")
        .append(member)
        .append("(nullptr, detail::ScopedDelete<")
        .append(typeName(((ObjectType) fd.getFieldType()).getRefer()))
        .append(">{a.resource()})");
    copy.append(", ")
        .append(member)
        .append("(generated_detail::copy_box(a.resource(), other.")
        .append(member)
        .append("))");
  }
  for (ReverseRelation rel : od.getReverseRelations()) {
    String member = relationName(rel) + "_";
    if (ReverseRelationNaming.oneToOne(rel)) {
      init.append(", ")
          .append(member)
          .append("(nullptr, detail::ScopedDelete<")
          .append(typeName(rel.getChild()))
          .append(">{a.resource()})");
      copy.append(", ")
          .append(member)
          .append("(generated_detail::copy_box(a.resource(), other.")
          .append(member)
          .append("))");
    } else {
      init.append(", ").append(member).append("(std::allocator_arg, a)");
      copy.append(", ")
          .append(member)
          .append("(std::allocator_arg, a, other.")
          .append(member)
          .append(")");
    }
  }
  line(
      out,
      "inline " + name + "::" + name + "(std::allocator_arg_t, Allocator a) " + init + " {}");
  line(
      out,
      "inline "
          + name
          + "::"
          + name
          + "(std::allocator_arg_t, Allocator a, const "
          + name
          + "& other) "
          + copy
          + " {}");
  line(out, "inline " + name + "::" + name + "(" + name + "&&) noexcept = default;");
  line(out, "inline " + name + "::~" + name + "() = default;");
  line(out, "inline EntityDescriptor " + name + "::entity_descriptor(Memory r) {");
  line(
      out,
      "EntityDescriptor d(std::allocator_arg, Allocator(r), ENTITY_NAME); d.table("
          + quote(od.getTableName())
          + ");");
  if (od.getDataService() != null) {
    line(out, "d.service(" + quote(od.getDataService().getName()) + ");");
  }
  for (FieldDescriptor fd : descriptorFields(od)) {
    String flags =
        (fd.isId() ? ".id()" : fd.isVersion() ? ".version()" : "")
            + (!fd.getBooleanAttribute("optional") ? ".not_null()" : "");
    line(
        out,
        "{ auto& property = d.property("
            + quote(RustFieldDescriptorNaming.rustStorageMemberName(fd))
            + ", DataType::"
            + dataType(fd)
            + ", "
            + quote(columnName(fd))
            + ")"
            + flags
            + ";");
    String inputColumn = CppJsonInputMetadata.column(fd);
    String physicalColumn = columnName(fd).isEmpty() ? canonical(fd) : columnName(fd);
    if (!inputColumn.equals(physicalColumn)) {
      line(out, "property.json_column_name.emplace(" + CppJsonInputMetadata.cppView(inputColumn) + ", r);");
    }
    String maxLength = fd.getAttributeValue("max");
    if (baseType(fd).equals("String")
        && !fd.getBooleanAttribute("isText")
        && maxLength != null
        && maxLength.matches("[1-9][0-9]*")) {
      line(out, "property.with_max_length(" + maxLength + ");");
    }
    String sqlType = fd.getAttributeValue(Attributes.SQL_TYPE);
    if (sqlType != null) {
      var numeric =
          Pattern.compile(
                  "(?i)^\\s*(?:NUMERIC|DECIMAL)\\s*\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\)\\s*$")
              .matcher(sqlType);
      if (numeric.matches()) {
        line(
            out,
            "property.with_numeric_precision("
                + numeric.group(1)
                + ").with_numeric_scale("
                + numeric.group(2)
                + ");");
      }
    }
    line(out, "(void)property; }");
  }
  for (FieldDescriptor fd :
      fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
    descriptorRelation(
        out,
        relationIdentity(fd),
        typeName(((ObjectType) fd.getFieldType()).getRefer()),
        canonical(fd),
        "id",
        false);
  }
  // Rust emits reverse descriptor attributes in one-to-one, then one-to-many order.
  for (ReverseRelation rel : java.util.stream.Stream.concat(
      RustObjectDescriptorNaming.rustOneToOneRelations(od).stream(),
      RustObjectDescriptorNaming.rustOneToManyRelations(od).stream()).toList()) {
    descriptorRelation(
        out,
        relationIdentity(rel),
        typeName(rel.getChild()),
        "id",
        canonical(rel.getProperty()),
        !ReverseRelationNaming.oneToOne(rel));
  }
  line(out, "d.mask_fields({" + String.join(",",
      CppFieldLayoutMetadata.auditMaskFields(od).stream().map(FieldDescriptorNaming::canonicalPropertyName)
          .map(CppCoreGenerator::quote).toList()) + "});");
  String auditLimit = CppFieldLayoutMetadata.auditValueMaxLen(od);
  if (auditLimit != null) {
    boolean wide = new java.math.BigInteger(auditLimit).bitLength() > 32;
    if (wide) {
      line(out, "static_assert(" + auditLimit + "ULL <= static_cast<unsigned long long>(static_cast<std::size_t>(-1)), \"audit_value_max_len exceeds target usize\");");
    }
    line(out, "d.audit_max_length(" + auditLimit + (wide ? "ULL" : "") + ");");
  }
  line(out, "return d; }");
  line(
      out,
      "inline Result<"
          + name
          + ", EntityError> "
          + name
          + "::from_compact_row(Memory r, CompactRow row) {");
  line(
      out,
      "using Outcome = Result<"
          + name
          + ", EntityError>; "
          + name
          + " result(std::allocator_arg, Allocator(r)); auto captured = detail::EntityRuntimeAccess::capture_dynamic_values(result.dynamic, row, field_layout(r)); if (!captured) { return Outcome::err(r, std::move(captured).error()); }");
  for (FieldDescriptor fd : fields(od)) {
    String variable = fieldName(fd) + "_lookup";
    line(out, "auto " + variable + " = GeneratedRelationAccess::lookupField(r, row, ENTITY_NAME, "
        + quote(canonical(fd)) + ", " + quote(columnName(fd)) + ", " + fd.isObjectProperty() + ");");
    line(out, "if (!" + variable + ") { return Outcome::err(r, std::move(" + variable + ").error()); }");
  }
  for (FieldDescriptor fd : fields(od)) {
    String field = fieldName(fd);
    line(
        out,
        "auto "
            + field
            + "_value = generated_detail::decode<"
            + storageType(fd)
            + ">(r, "
            + field
            + "_lookup.value().value, ENTITY_NAME, "
            + quote(canonical(fd))
            + ");");
    line(
        out,
        "if (!"
            + field
            + "_value) { return Outcome::err(r, std::move("
            + field
            + "_value).error()); }");
    line(out, "result." + field + "_ = std::move(" + field + "_value).value();");
  }
  for (FieldDescriptor fd :
      fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
    decodeRelation(
        out,
        name,
        relationName(fd),
        relationIdentity(fd),
        typeName(((ObjectType) fd.getFieldType()).getRefer()));
  }
  // Source reverse relations are installed runtime views, not struct fields
  // reconstructed from arbitrary raw columns. Keep the local fallback empty.
  line(
      out,
      "result.load_state ="
          + " row.indexed_load_state(detail::ContextArena::from_memory(r).loaded_snapshots(),"
          + " field_layout(r));");
  for (FieldDescriptor fd : fields(od)) {
    if (fd.isObjectProperty()) {
      String variable = fieldName(fd) + "_lookup.value()";
      line(out, "if (" + variable + ".alias_present) { auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();");
      line(out, "if (!" + variable + ".object_alias && !row.is_loaded_relation(" + quote(columnName(fd)) + ")) { result.load_state.mark_unloaded(" + quote(relationIdentity(fd)) + ", &pool).value(); }");
      line(out, "result.load_state.mark_loaded(" + quote(canonical(fd)) + ", &pool).value(); }");
    }
  }
  line(out, "result.root.set_original_compact_row(ENTITY_NAME, row); return Outcome::ok(r, std::move(result)); }");
  line(
      out,
      "inline MutationValues "
          + name
          + "::into_values() && { auto r = memory_resource(); MutationValues values(r);");
  for (FieldDescriptor fd : fields(od)) {
    line(
        out,
        "values.fields.emplace(String("
            + quote(canonical(fd))
            + ", r), generated_detail::encode(r, "
            + fieldName(fd)
            + "_));");
  }
  line(out, "detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);");
  for (FieldDescriptor fd :
      fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
    injectRelation(out, relationName(fd), relationIdentity(fd), false);
  }
  for (ReverseRelation rel : od.getReverseRelations()) {
    injectRelation(out, relationName(rel), relationIdentity(rel), !ReverseRelationNaming.oneToOne(rel));
  }
  line(out, "inject_runtime(values); return values; }");
  for (FieldDescriptor fd :
      fields(od).stream().filter(FieldDescriptor::isObjectProperty).toList()) {
    String target = typeName(((ObjectType) fd.getFieldType()).getRefer()),
        relation = relationName(fd);
    line(
        out,
        "inline "
            + name
            + "& "
            + name
            + "::update_"
            + relation
            + "(const "
            + target
            + "& value) { "
            + relation
            + "_ = detail::make_box<"
            + target
            + ">(memory_resource(), value); update_"
            + fieldName(fd)
            + "(value.id()); return *this; }");
  }
}

private String camelAssist(String text, String namespace) {
  java.util.regex.Matcher code = java.util.regex.Pattern.compile("`([^`]*)`").matcher(text);
  StringBuffer result = new StringBuffer();
  Set<String> protocols =
      Set.of(
          namespace,
          "user_context",
          "query_factory",
          "audit_as",
          "memory_resource",
          "get_entity",
          "canonical_name",
          "into_query",
          "DATABASE_URL_ENV",
          "target_state",
          "insert_resource",
          "static_cast",
          "const_cast",
          "reinterpret_cast",
          "dynamic_cast",
          "ensure_schema",
          "apply_to",
          "decode_json_entity",
          "decode_json_entities",
          "into_json",
          "chunk_size");
  while (code.find()) {
    // A quoted result key is model data, not an application identifier.
    if (code.group(1).startsWith("\"") && code.group(1).endsWith("\"")) {
      code.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(code.group()));
      continue;
    }
    java.util.regex.Matcher words =
        java.util.regex.Pattern.compile("[A-Za-z_][A-Za-z_0-9]*").matcher(code.group(1));
    StringBuffer snippet = new StringBuffer();
    while (words.find()) {
      String word = words.group();
      boolean standard = code.group(1).substring(0, words.start()).endsWith("std::");
      words.appendReplacement(snippet, protocols.contains(word) || standard ? word : camel(word));
    }
    words.appendTail(snippet);
    code.appendReplacement(result, java.util.regex.Matcher.quoteReplacement("`" + snippet + "`"));
  }
  code.appendTail(result);
  return result.toString();
}

