    if (entities.stream().anyMatch(entity -> entity.getDepth() > 0 && !entity.isConstant()
        && fields(entity).stream().anyMatch(field -> baseType(field).equals("String")
            && !field.isString() && !field.isJsonLiteral()
            && (field.isNumber() || field.getBooleanAttribute("isNumber"))))) {
      line(out, "Numeric sample recipes for String-mapped aliases retain the original integer operand. Generated typed Checkers can reject entity materialization before custom CheckerLogic runs. The runtime does not silently convert the operand to text; modules without those checkers retain the provider's actual behavior. Use explicitly typed application values when this model's sample save fails.");
    }
    line(out, "Sample progress: register an application-owned `SampleDataLogSink` through `user_context.insert_resource(owner, static_cast<SampleDataLogSink&>(sink))`. Its synchronous `info(user_context, message)` receives the original sample Info messages in execution order. Allocate the sink in the declared Global/User owner; `memory_resource()` must identify that owner. Missing or disabled sinks do not format messages. Messages are callback borrows; retaining them requires an explicit copy into the sink owner's allocator. Pending re-polls do not repeat start; cancellation and save failure emit no successful completion. A callback must not close its active Context, and exceptions propagate as operation failure. This sample-specific sink does not replace SQL diagnostics or audit sinks.");
    if (entities.stream().anyMatch(entity -> entity.getDepth() > 0 && !entity.isConstant()
        && CppFieldLayoutMetadata.fields(entity).stream().anyMatch(field -> baseType(field).equals("Json") && (field.isString() || field.isJsonLiteral())))) {
      line(out, "JSON sample text follows the locked source setter operand and can fail typed checking. The sample generator does not silently turn that text into valid JSON. Initialize JSON models with explicit typed values when sample generation reports an error. Complete quoted JSON-literal source generation also has a retained compiler failure; no complete sample parity is advertised for that configuration.");
    }
    line(out, "Deletion: `entity.markForDeletion()` records deletion in the ledger and returns"
        + " the model for chaining. Save through the audited save API; marking alone does"
        + " not execute SQL. Versioned SQLite models use the runtime soft-delete protocol.");
    line(out, "Projection shortcuts: `selectSelfFields()` and `selectSelfWithoutParent()`"
        + " both select native fields, including inherited fields as the original generator"
        + " does. `selectAll()` also selects forward and reverse to-one relations;"
        + " `selectChildren()` adds reverse collections, and `selectAny()` aliases it."
        + " These do not replace `enhanceChildrenIfNeeded()` for polymorphic descendants."
        + " Named relation selections can include soft-deleted child rows; they do not"
        + " automatically apply a child Q entry's default live-row filter. Use an explicit"
        + " select...With(child_request) to carry the child's filters and projection.");
    line(out, "Runtime attachment: `entity.attachRuntimeStateRecursive(target_state)` adopts"
        + " pending mutations and preserves the entity's loaded snapshot. It recursively"
        + " attaches stored forward objects; it does not load relations or traverse graph"
        + " lookups/reverse collections. Both states must belong to the same Context;"
        + " cross-domain retention requires an explicit destination copy.");
    List<String> sourceIdentityDifferences = entities.stream().flatMap(entity -> descriptorFields(entity).stream())
        .filter(field -> !canonical(field).equals(RustFieldDescriptorNaming.rustStorageMemberName(field)))
        .map(field -> quote(canonical(field)) + " -> " + quote(RustFieldDescriptorNaming.rustStorageMemberName(field)))
        .distinct().toList();
    if (!sourceIdentityDifferences.isEmpty()) {
      line(out, "Source metadata boundary: query projections retain storage names while descriptors retain the original Rust member identities: `"
          + String.join(", ", sourceIdentityDifferences) + "`. Queries of these fields can preserve the original unknown-field SQL failure. The adapter does not silently rename query fields to make that source configuration succeed.");
    }
    line(out, "## Business IDs");
    for (ObjectDescriptor entity : entities) {
      for (FieldDescriptor field : fields(entity)) {
        if (CppBusinessIdMetadata.isBusinessId(field)) {
          String type = applicationType(field);
          line(
              out,
              "- `"
                  + type
                  + "::create(user_context.memory_resource(), text)` trims and rejects blank text;"
                  + " `asStr()` exposes canonical text. Model setter `"
                  + camel("update_" + fieldName(field))
                  + "(const "
                  + type
                  + "&)` and scalar predicates accept this distinct type."
                  + " `definition(user_context.memory_resource())` exposes its configured profile."
                  + " Creation uses the trusted active root, allocation service and fix evidence;"
                  + " dirty Business IDs are immutable on update.");
        }
      }
    }
    if (entities.stream()
        .flatMap(entity -> fields(entity).stream())
        .anyMatch(CppBusinessIdMetadata::isBusinessId)) {
      line(
          out,
          "setup installs SQLite Business-ID infrastructure. Register an explicit"
              + " BusinessIdKeyProvider through UserContext before daily-permuted-v1 creation; no"
              + " default key or hidden owner is introduced. Use with_active_root before allocating"
              + " aggregate IDs.");
    }
    line(out, "## Model relation evaluation");
    line(
        out,
        "Model evalX() and E.getX() share the runtime relation rules. Loaded empty lists are"
            + " values, selected empty to-one relations are Null, and missing views are NotLoaded."
            + " Returned entity/list values are checked Context borrows. Reverse XHandle() methods"
            + " expose the immutable query-installed view; existing mutable list getters remain"
            + " explicit model-local graph construction adapters. No getter performs implicit"
            + " SQL.");
    line(out, "## Checker and behavior assembly");
    line(out, "Wire metadata: `generatedWireFieldMappings(user_context)` returns Context-owned typed maps from canonical model field names to the selected JSON wire spelling. Like the original template, each entity entry lists its own fields; it does not flatten inherited fields or rename relation keys to FK storage keys. `generatedWireFieldAliases(user_context)` returns the separately defined empty legacy-alias map. These functions do not install metadata, authorize client input or provide a transport endpoint. Explicit destination copying is required to retain the maps after Context close.");
    line(
        out,
        "`configureRuntime(user_context, filename)` installs generated metadata, checkers and"
            + " behaviors, the SQLite provider, scoped persistent IDs and the application executor."
            + " It does not create schema. `setup(user_context, filename)` performs that configuration"
            + " and waits for `user_context.ensure_schema().wait()`; its default filename is `:memory:`.");
    line(
        out,
        "Use `module(user_context)` for metadata-only registration, or"
            + " `moduleWithCheckers(user_context)`, `moduleWithBehaviors(user_context)` or"
            + " `moduleWithBehaviorsAndCheckers(user_context)` for explicit assembly. Keep"
            + " handwritten logic outside generated files.");
    line(out, "For custom assembly, call `configureRuntime(user_context, filename)` first, then"
        + " register application-owned Checker/Behavior overrides with a module and apply it"
        + " before `user_context.ensure_schema().wait()` or business execution. Calling"
        + " `configureRuntime` or `setup` again installs defaults and replaces those registrations.");
    if (hasGeneratedBootstrap(entities)) {
      line(out, "All four module factories register schema bootstrap. Schema initialization prepares"
          + " the generated Domain Root and active-root binding; reuse that root instead of inserting"
          + " a second ID 1. Repeated initialization preserves existing root values. Bootstrap"
          + " errors propagate; do not treat a failed `setup` as a usable initialized Context.");
    }
    for (ObjectDescriptor od : entities) {
      String name = typeName(od);
      line(
          out,
          "- Extend `"
              + name
              + "CheckerLogic` and override `checkAndFix"
              + name
              + "(user_context, entity, status, location, results)`. Allocate logic in an explicit"
              + " Context, create `"
              + name
              + "Checker` with that logic and register its `TypedEntityChecker` adapter. The"
              + " built-in Context/time fixes and predefined update-load checks run before custom"
              + " logic.");
      line(
          out,
          "- `"
              + name
              + "Behavior` preserves the EntityDataServiceBehavior SPI; runtime hook names retain"
              + " snake_case.");
    }
    for (ObjectDescriptor od : entities) {
      for (FieldDescriptor field : fields(od)) {
        if (field.isObjectProperty()) {
          relationIdentityAssist(out, typeName(od), relationName(field), relationIdentity(field));
        }
      }
      for (ReverseRelation relation : od.getReverseRelations()) {
        relationIdentityAssist(out, typeName(od), relationName(relation), relationIdentity(relation));
      }
    }
    line(out, "Aggregate composition: `parent.includePendingMutationsFrom(child)` copies the child's pending additions, updates and deletions into the parent's Context for its next audited Save. Set modeled relationships before composition. It returns a checked Result; it does not load a relation, run SQL or save either object. The source retains its pending ledger for retry; original-version conflicts reject composition without partially merging. Cross-domain composition is an explicit destination copy: nested values and snapshots belong to the receiving Context, and closing the source does not invalidate them. It does not rebind the source object or extend either Context lifetime. The runtime owns ledger merging and Context validation.");
    for (ObjectDescriptor od : entities) {
      for (FieldDescriptor field : fields(od)) {
        if (scalarDiagnosticAlias(field)) {
          line(out, "Scalar diagnostic repair for " + typeName(od) + ": `\"" + canonical(field)
              + "\"` is the metadata and diagnostic path. Q `" + camel("select_" + canonical(field))
              + "()` / `" + camel("unselect_" + canonical(field)) + "()` and E `"
              + camel("get_" + canonical(field)) + "()` delegate to the existing escaped methods `"
              + camel("select_" + fieldName(field)) + "()`, `" + camel("unselect_" + fieldName(field))
              + "()` and `" + camel("get_" + fieldName(field))
              + "()`. These aliases preserve Context binding, take no extra Context argument and issue no implicit queries.");
        }
      }
    }
    return camelAssist(out.toString(), ns);
  }

  /** Local, offline entry point; uses exactly the service's model parser/discovery. */
  public static void main(String[] args) throws Exception {
    Set<String> flags = args.length < 2 ? Set.of() : new HashSet<>(Arrays.asList(args).subList(2, args.length));
    if (args.length < 2 || !Set.of("--qualify-inheritance", "--qualify-constants").containsAll(flags)) {
      throw new IllegalArgumentException("Usage: CppCoreGenerator MODEL OUTPUT_DIRECTORY [--qualify-inheritance] [--qualify-constants]");
    }
    Path model = Path.of(args[0]).toAbsolutePath();
    Path output = Path.of(args[1]).toAbsolutePath().normalize();
    GenerateContext context = new GenerateContext(SCOPE, model.getFileName().toString());
    context.setEntranceFile(model.getFileName().toString());
    context.appendFile(model.getFileName().toString(), Files.readAllBytes(model));
    BaseDomainManager manager = new BaseDomainManager();
    Domain domain = manager.getDomain(manager.parse(context));
    List<GeneratedFile> generated = args.length > 2
        ? new CppCoreGenerator(flags.contains("--qualify-inheritance"), flags.contains("--qualify-constants")).generate(domain)
        : new DomainGenerationService().generateDomainFiles(domain, SCOPE);
    for (GeneratedFile file : generated) {
      Path target = output.resolve(file.getPath()).normalize();
      if (!target.startsWith(output)) {
        throw new IllegalArgumentException("Invalid generated path: " + file.getPath());
      }
      Files.createDirectories(target.getParent());
      Files.write(target, file.getData());
    }
  }
}

runtime_constructor:
explicit EntityQuery(UserContext& user_context, bool minimal = false, bool live_rows = true)
    requires(!Purposed)
    : binding_(user_context),
      description_(user_context.make_ref<detail::QueryDescription>(T::ENTITY_NAME)) {
    auto descriptor = T::entity_descriptor(memory_resource());
    if constexpr (requires { T::QUERY_IDENTITY_FIELDS; }) {
        for (auto field : T::QUERY_IDENTITY_FIELDS) {
            description().query.project(field);
        }
    }
    for (const auto& property : descriptor.properties) {
        if constexpr (!requires { T::QUERY_IDENTITY_FIELDS; }) {
            if (property.is_id || property.is_version) {
                description().query.project(property.name);
            }
        }
        if (live_rows && property.is_version) {
            description().query.and_filter(
                Expr::gt(memory_resource(), property.name, std::int64_t(0)));
        }
    }
    if (!minimal) {
        if constexpr (requires { T::QUERY_PROJECTION_FIELDS; }) {
            for (auto field : T::QUERY_PROJECTION_FIELDS) {
                description().query.project(field);
            }
        } else {
            for (const auto& property : descriptor.properties) {
                description().query.project(property.name);
            }
        }
    }
}
